// Non-interactive service hosts (@include * reaches them too) can hang on
// Shell/COM work a real desktop session handles fine. Checks capability (a
// visible window station) rather than process name, so any app's own
// file-picker dialog still gets covered. Fails closed on API failure.
static bool IsCurrentProcessInteractive()
{
    static int cached = -1;
    if (cached == -1)
    {
        HWINSTA hwinsta = GetProcessWindowStation();
        USEROBJECTFLAGS flags = {};
        DWORD needed = 0;
        cached = (hwinsta &&
                  GetUserObjectInformationW(hwinsta, UOI_FLAGS, &flags,
                                            sizeof(flags), &needed) &&
                  (flags.dwFlags & WSF_VISIBLE)) ? 1 : 0;
    }
    return cached == 1;
}

