static float NavPillWidth(float scale)
{
    return NAV_PILL_WIDTH_DIP * scale;
}

static float NavPillHeight(float scale)
{
    return NAV_PILL_HEIGHT_DIP * scale;
}

static float NavPillRadius(float scale, float width)
{
    return (std::min)(NAV_PILL_RADIUS_DIP * scale, width * 0.5f);
}

static float NavPillHalfPad(float itemH, float scale)
{
    return (itemH - NavPillHeight(scale)) * 0.5f;
}

