// Fixed shortcuts shown in the collapsed rail below the toggle button:
// Separator entries are purely decorative (drawn by the rail itself, no
// HWND); every other kind owns one child button window. Kept as a single
// ordered list (rather than separate "rows" and "buttons" collections) so
// layout, creation and painting all walk the same sequence.
enum class RailShortcutKind : unsigned char {
    Separator,
    Home,
    Desktop,
    Downloads,
    Documents,
    Pictures,
    Music,
    Videos,
    Drive,
};

struct RailShortcutButtonState {
    RailShortcutKind kind = RailShortcutKind::Separator;
    HWND button = nullptr;
    wchar_t glyph = L'\0';
    // Only meaningful for RailShortcutKind::Drive -- the root path (e.g.
    // "C:\\") used both as the navigation target and as a stable identity
    // when the drive list is rebuilt.
    std::wstring drivePath;
    // Resolved once, in AppendRailShortcut, and reused both for the click
    // (ActivateRailShortcut) and the tooltip -- so the tooltip always
    // describes exactly where the click will go, and Home's registry read
    // + the known-folder resolution only happen once per shortcut, not
    // once at creation and again on every click.
    std::wstring targetPath;
    // Shell's own localized display name for targetPath (e.g. "Documentos"
    // on a pt-BR system), shown as the button's tooltip.
    std::wstring tooltipText;
};

struct NavigationButtonState {
    HWND button = nullptr;
    HWND rail = nullptr;
    HWND root = nullptr;
    HWND tab = nullptr;
    // Bottom inset measured from DirectUI's live StatusBarModule paint. Unlike
    // an absolute Y coordinate, this stays valid while the tab is resized.
    int statusBarBottomInset = 0;
    bool statusBarBottomInsetValid = false;
    // SHELLDLL_DefView under this tab, cached as a handle only -- its rect
    // is read fresh every time (see PositionNavigationButton) rather than
    // stored here, since Explorer keeps it correctly laid out (excluding
    // the status bar) at all times and caching the rect itself is what
    // previously left the rail's collapsed height stuck at a stale value
    // across minimize/maximize. Re-resolved automatically whenever
    // IsWindow() on it goes false (covers Explorer recreating the view).
    HWND shellView = nullptr;
    RECT nativeRect = {};
    RECT appliedRect = {};
    bool nativeRectValid = false;
    float railBlend = 0.0f;
    float railBlendFrom = 0.0f;
    float railBlendTarget = 0.0f;
    ULONGLONG railBlendStartTick = 0;
    bool railBlendAnimating = false;
    bool railVisualInitialized = false;
    float glyphScaleX = 1.0f;
    float glyphScaleY = 1.0f;
    float glyphScaleFromX = 1.0f;
    float glyphScaleFromY = 1.0f;
    float glyphScaleTargetX = 1.0f;
    float glyphScaleTargetY = 1.0f;
    ULONGLONG glyphScaleStartTick = 0;
    ULONGLONG glyphScaleDurationMs = 0;
    bool glyphScaleAnimating = false;
    ULONGLONG glyphPressedAtTick = 0;
    bool glyphReleasePending = false;
    // Fixed navigation shortcuts (Home / libraries / drives) shown in the
    // collapsed rail below the toggle button. Built once by
    // EnsureNavigationRailShortcuts; the drive entries can be rebuilt later
    // by RefreshNavigationRailShortcutDrives.
    std::vector<RailShortcutButtonState> shortcuts;
    bool shortcutsBuilt = false;
    int shortcutsScrollOffset = 0;
    // One shared tooltip control for all of this host's shortcut buttons
    // (TTF_SUBCLASS on each button handles show/hide automatically).
    HWND tooltip = nullptr;
};

