class ScopedPaneCommandContext {
public:
    ScopedPaneCommandContext(void* command, PaneCommandSource source,
                             unsigned long call, bool captureCommand = true)
        : previousCommand_(g_activePaneCommand),
          previousLoggedCommand_(g_loggedPaneCommand),
          previousSource_(g_activePaneCommandSource),
          previousCall_(g_activePaneCommandCall) {
        if (captureCommand)
            g_activePaneCommand = command;
        g_loggedPaneCommand = command;
        g_activePaneCommandSource = source;
        g_activePaneCommandCall = call;
    }

    ~ScopedPaneCommandContext() {
        g_activePaneCommand = previousCommand_;
        g_loggedPaneCommand = previousLoggedCommand_;
        g_activePaneCommandSource = previousSource_;
        g_activePaneCommandCall = previousCall_;
    }

    ScopedPaneCommandContext(const ScopedPaneCommandContext&) = delete;
    ScopedPaneCommandContext& operator=(const ScopedPaneCommandContext&) =
        delete;

private:
    void* previousCommand_;
    void* previousLoggedCommand_;
    PaneCommandSource previousSource_;
    unsigned long previousCall_;
};

